#include <vector>
#include <unordered_map>
#include <algorithm>

class Solution {
public:
    int minSubarray(std::vector<int>& nums, int p) {
        long long total = 0;
        for (int x : nums) total += x;
        int rem = total % p;
        if (rem == 0) return 0;
        std::unordered_map<int, int> pos;
        pos[0] = -1;
        int cur = 0, n = nums.size(), ans = n;
        for (int i = 0; i < n; ++i) {
            cur = (cur + nums[i]) % p;
            int needed = (cur - rem + p) % p;
            if (pos.count(needed)) {
                ans = std::min(ans, i - pos[needed]);
            }
            pos[cur] = i;
        }
        return ans < n ? ans : -1;
    }
};

import java.util.*;

class Solution {
    public int minSubarray(int[] nums, int p) {
        long total = 0;
        for (int x : nums) total += x;
        int rem = (int)(total % p);
        if (rem == 0) return 0;
        Map<Integer, Integer> pos = new HashMap<>();
        pos.put(0, -1);
        int cur = 0, n = nums.length, ans = n;
        for (int i = 0; i < n; i++) {
            cur = (cur + nums[i]) % p;
            int needed = (cur - rem + p) % p;
            if (pos.containsKey(needed)) {
                ans = Math.min(ans, i - pos.get(needed));
            }
            pos.put(cur, i);
        }
        return ans < n ? ans : -1;
    }
}

var minSubarray = function(nums, p) {
    let total = 0n;
    for (const x of nums) total += BigInt(x);
    const bp = BigInt(p);
    const rem = Number(total % bp);
    if (rem === 0) return 0;
    const pos = new Map();
    pos.set(0, -1);
    let cur = 0, n = nums.length, ans = n;
    for (let i = 0; i < n; i++) {
        cur = (cur + nums[i]) % p;
        const needed = (cur - rem + p) % p;
        if (pos.has(needed)) {
            ans = Math.min(ans, i - pos.get(needed));
        }
        pos.set(cur, i);
    }
    return ans < n ? ans : -1;
};
